<?php
require 'config.php'; require_login();
$total=$pdo->query("SELECT COUNT(*) FROM barang")->fetchColumn();
$stok=$pdo->query("SELECT COALESCE(SUM(stok),0) FROM barang")->fetchColumn();
$low=$pdo->query("SELECT COUNT(*) FROM barang WHERE stok<=stok_minimum")->fetchColumn();
$today=$pdo->query("SELECT COUNT(*) FROM transaksi_barang WHERE DATE(tanggal)=CURDATE()")->fetchColumn();
$recent=$pdo->query("SELECT t.*,b.nama_barang,u.nama FROM transaksi_barang t JOIN barang b ON t.id_barang=b.id_barang JOIN users u ON t.id_user=u.id_user ORDER BY t.tanggal DESC LIMIT 6")->fetchAll(PDO::FETCH_ASSOC);
$lowItems=$pdo->query("SELECT * FROM barang WHERE stok<=stok_minimum ORDER BY stok ASC LIMIT 5")->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard — Inventaris</title><link rel="stylesheet" href="style.css"></head><body>
<?php include 'nav.php'; ?><main class="main"><header class="page-head"><div><p class="eyebrow">OVERVIEW</p><h1>Dashboard</h1><p class="muted">Ringkasan aktivitas gudang hari ini.</p></div><span class="user-chip"><?= htmlspecialchars($_SESSION['user']['nama']) ?></span></header>
<section class="stats"><div class="stat"><span>Total jenis barang</span><strong><?= $total ?></strong><small>Item terdaftar</small></div><div class="stat"><span>Total stok</span><strong><?= $stok ?></strong><small>Unit di gudang</small></div><div class="stat"><span>Stok menipis</span><strong class="<?= $low?'warning-text':'' ?>"><?= $low ?></strong><small>Perlu diperiksa</small></div><div class="stat"><span>Transaksi hari ini</span><strong><?= $today ?></strong><small>Barang masuk / keluar</small></div></section>
<div class="content-grid"><section class="panel"><div class="panel-head"><h2>Transaksi terbaru</h2><a href="transaksi.php">Lihat semua →</a></div><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Jenis</th><th>Jumlah</th><th>Petugas</th><th>Tanggal</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><?= htmlspecialchars($r['nama_barang']) ?></td><td><span class="badge <?= $r['jenis_transaksi']==='masuk'?'green':'orange' ?>"><?= ucfirst($r['jenis_transaksi']) ?></span></td><td><?= $r['jumlah'] ?></td><td><?= htmlspecialchars($r['nama']) ?></td><td><?= date('d/m H:i',strtotime($r['tanggal'])) ?></td></tr><?php endforeach ?><?php if(!$recent): ?><tr><td colspan="5" class="empty">Belum ada transaksi.</td></tr><?php endif ?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><h2>Stok perlu perhatian</h2><a href="barang.php">Kelola →</a></div><?php foreach($lowItems as $item): ?><div class="low-item"><div><b><?= htmlspecialchars($item['nama_barang']) ?></b><small><?= htmlspecialchars($item['kategori']) ?></small></div><span class="warning-text"><?= $item['stok'] ?> <?= htmlspecialchars($item['satuan']) ?></span></div><?php endforeach ?><?php if(!$lowItems): ?><p class="empty">Semua stok masih aman.</p><?php endif ?></section></div></main></body></html>
